const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/checklist/list_templates',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[inspection_type_id]': 'SOME_ARRAY_VALUE',
    'filters[needs_update]': 'SOME_BOOLEAN_VALUE',
    'filters[response_set_id]': 'SOME_ARRAY_VALUE',
    'filters[trade_ids]': 'SOME_ARRAY_VALUE',
    'filters[query]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/checklist/list_templates?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Binspection_type_id%5D=SOME_ARRAY_VALUE&filters%5Bneeds_update%5D=SOME_BOOLEAN_VALUE&filters%5Bresponse_set_id%5D=SOME_ARRAY_VALUE&filters%5Btrade_ids%5D=SOME_ARRAY_VALUE&filters%5Bquery%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

